using AppCondominio.SharedKernel;
namespace AppCondominio.Modules.Maintenance.Domain;
public enum AssetStatus{Active=0,Inactive=1,Retired=2} public enum IncidentStatus{Open=0,InProgress=1,Resolved=2,Cancelled=3} public enum WorkOrderStatus{Draft=0,Assigned=1,InProgress=2,Completed=3,Cancelled=4}
public sealed class MaintenanceAsset:AggregateRoot{private MaintenanceAsset(Guid id,Guid communityId,string code,string name,string category,string location):base(id){CommunityId=communityId;Code=Req(code);Name=Req(name);Category=Req(category);Location=Req(location);} public Guid CommunityId{get;private set;} public string Code{get;private set;} public string Name{get;private set;} public string Category{get;private set;} public string Location{get;private set;} public AssetStatus Status{get;private set;} public static MaintenanceAsset Create(Guid communityId,string code,string name,string category,string location)=>communityId==Guid.Empty?throw new ArgumentException("Community required."):new(Guid.NewGuid(),communityId,code,name,category,location); public void Retire()=>Status=AssetStatus.Retired; static string Req(string x)=>string.IsNullOrWhiteSpace(x)?throw new ArgumentException("Required value missing."):x.Trim();}
public sealed class PreventivePlan:AggregateRoot{private PreventivePlan(Guid id,Guid communityId,Guid assetId,string name,int frequencyDays,DateOnly nextDueDate):base(id){CommunityId=communityId;AssetId=assetId;Name=Req(name);FrequencyDays=frequencyDays;NextDueDate=nextDueDate;} public Guid CommunityId{get;private set;} public Guid AssetId{get;private set;} public string Name{get;private set;} public int FrequencyDays{get;private set;} public DateOnly NextDueDate{get;private set;} public bool IsActive{get;private set;}=true; public static PreventivePlan Create(Guid communityId,Guid assetId,string name,int frequencyDays,DateOnly nextDueDate){if(communityId==Guid.Empty||assetId==Guid.Empty||frequencyDays<=0)throw new ArgumentException("Invalid preventive plan.");return new(Guid.NewGuid(),communityId,assetId,name,frequencyDays,nextDueDate);} public void MarkExecuted(DateOnly executedOn){if(!IsActive)throw new InvalidOperationException("Plan inactive.");NextDueDate=executedOn.AddDays(FrequencyDays);} static string Req(string x)=>string.IsNullOrWhiteSpace(x)?throw new ArgumentException("Required value missing."):x.Trim();}
public sealed class MaintenanceIncident:AggregateRoot{private MaintenanceIncident(Guid id,Guid communityId,Guid? assetId,string title,string description,string priority,string reportedBy):base(id){CommunityId=communityId;AssetId=assetId;Title=Req(title);Description=Req(description);Priority=Req(priority);ReportedBy=Req(reportedBy);ReportedAtUtc=DateTimeOffset.UtcNow;} public Guid CommunityId{get;private set;} public Guid? AssetId{get;private set;} public string Title{get;private set;} public string Description{get;private set;} public string Priority{get;private set;} public string ReportedBy{get;private set;} public DateTimeOffset ReportedAtUtc{get;private set;} public IncidentStatus Status{get;private set;} public void Start()=>Status=Status==IncidentStatus.Open?IncidentStatus.InProgress:throw new InvalidOperationException("Incident cannot start."); public void Resolve()=>Status=Status is IncidentStatus.Open or IncidentStatus.InProgress?IncidentStatus.Resolved:throw new InvalidOperationException("Incident cannot resolve."); public static MaintenanceIncident Create(Guid communityId,Guid? assetId,string title,string description,string priority,string reportedBy)=>communityId==Guid.Empty?throw new ArgumentException("Community required."):new(Guid.NewGuid(),communityId,assetId,title,description,priority,reportedBy); static string Req(string x)=>string.IsNullOrWhiteSpace(x)?throw new ArgumentException("Required value missing."):x.Trim();}
public sealed class WorkOrder:AggregateRoot{private WorkOrder(Guid id,Guid communityId,Guid? assetId,Guid? incidentId,Guid? preventivePlanId,string number,string title):base(id){CommunityId=communityId;AssetId=assetId;IncidentId=incidentId;PreventivePlanId=preventivePlanId;Number=Req(number);Title=Req(title);CreatedAtUtc=DateTimeOffset.UtcNow;} public Guid CommunityId{get;private set;} public Guid? AssetId{get;private set;} public Guid? IncidentId{get;private set;} public Guid? PreventivePlanId{get;private set;} public string Number{get;private set;} public string Title{get;private set;} public WorkOrderStatus Status{get;private set;} public string? AssignedTo{get;private set;} public decimal ActualCost{get;private set;} public string? ProcurementReference{get;private set;} public DateTimeOffset CreatedAtUtc{get;private set;} public DateTimeOffset? CompletedAtUtc{get;private set;} public static WorkOrder Create(Guid communityId,Guid? assetId,Guid? incidentId,Guid? preventivePlanId,string number,string title)=>communityId==Guid.Empty?throw new ArgumentException("Community required."):new(Guid.NewGuid(),communityId,assetId,incidentId,preventivePlanId,number,title); public void Assign(string to){if(Status!=WorkOrderStatus.Draft)throw new InvalidOperationException("Only draft can be assigned.");AssignedTo=Req(to);Status=WorkOrderStatus.Assigned;} public void Start(){if(Status!=WorkOrderStatus.Assigned)throw new InvalidOperationException("Only assigned can start.");Status=WorkOrderStatus.InProgress;} public void Complete(decimal actualCost,string? procurementReference){if(Status!=WorkOrderStatus.InProgress)throw new InvalidOperationException("Only in-progress can complete.");if(actualCost<0)throw new ArgumentOutOfRangeException(nameof(actualCost));ActualCost=decimal.Round(actualCost,2);ProcurementReference=string.IsNullOrWhiteSpace(procurementReference)?null:procurementReference.Trim();Status=WorkOrderStatus.Completed;CompletedAtUtc=DateTimeOffset.UtcNow;} static string Req(string x)=>string.IsNullOrWhiteSpace(x)?throw new ArgumentException("Required value missing."):x.Trim();}
public sealed record MaintenanceKpi(int ActiveAssets,int OpenIncidents,int DuePreventivePlans,int OpenWorkOrders,decimal CompletedWorkCost);